            ['xs' => 'text-xs', 'md' => 'text-base', 'lg' => 'text-lg'][$size] ?? 'text-sm',
            Shades::primary($color),
            // Rhythm and structure.
            '[&>*:first-child]:mt-0 [&>*:last-child]:mb-0 [&_p]:my-3 [&_p]:leading-relaxed',
            '[&_h1]:mt-6 [&_h1]:mb-3 [&_h1]:text-[1.6em] [&_h1]:font-semibold [&_h2]:mt-6 [&_h2]:mb-2 [&_h2]:text-[1.35em] [&_h2]:font-semibold [&_h3]:mt-5 [&_h3]:mb-2 [&_h3]:text-[1.15em] [&_h3]:font-semibold [&_h4]:mt-4 [&_h4]:mb-1 [&_h4]:font-semibold',
            '[&_ul]:my-3 [&_ul]:list-disc [&_ul]:pl-6 [&_ol]:my-3 [&_ol]:list-decimal [&_ol]:pl-6 [&_li]:my-1 [&_li>p]:my-1 [&_ul_ul]:my-1 [&_ol_ol]:my-1',
            '[&_a]:underline [&_a]:underline-offset-2 [&_a:hover]:decoration-current [&_strong]:font-semibold',
            '[&_blockquote]:my-4 [&_blockquote]:border-l-4 [&_blockquote]:pl-4 [&_blockquote]:italic',
            '[&_:not(pre)>code]:rounded [&_:not(pre)>code]:px-1 [&_:not(pre)>code]:py-0.5 [&_:not(pre)>code]:font-mono [&_:not(pre)>code]:text-[0.85em]',
            '[&_pre]:my-4 [&_pre]:overflow-x-auto [&_pre]:rounded-lg [&_pre]:p-3 [&_pre]:font-mono [&_pre]:text-xs [&_pre]:leading-5',
            '[&_hr]:my-6 [&_img]:my-4 [&_img]:max-w-full [&_img]:rounded-md',
            '[&_table]:my-4 [&_table]:w-full [&_table]:border-collapse [&_th]:border-b [&_th]:px-2 [&_th]:py-1 [&_th]:text-left [&_th]:font-semibold [&_td]:border-b [&_td]:px-2 [&_td]:py-1',
            '[&_.mention]:rounded [&_.mention]:px-1 [&_.mention]:font-medium',
            $accentMap[$color] ?? $accentMap['base'],
        ]));
    }

    public function render(): View|Closure|string
    {
        return view('fltc::components.prose');
    }
}
